'use strict';
// Parse a compact duration string such as "1h30m", "45s" or "2d4h" into
// milliseconds.
const UNITS = [
  ['d', 86400000],
  ['h', 3600000],
  ['m', 60000],
  ['s', 1000],
];

// Anchored and each unit optional exactly once, so the pattern also enforces
// the largest-first ordering and rejects repeats and stray characters.
const DURATION_PATTERN = /^(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/;

function parseDuration(input) {
  const match = typeof input === 'string' && DURATION_PATTERN.exec(input);
  if (!match || !match.slice(1).some((group) => group !== undefined)) {
    throw new RangeError(`invalid duration: ${String(input)}`);
  }
  return UNITS.reduce(
    (total, [, size], index) => total + Number(match[index + 1] || 0) * size,
    0
  );
}

function formatDuration(ms) {
  if (!Number.isFinite(ms) || ms < 0) {
    throw new RangeError(`cannot format duration: ${ms}`);
  }
  let remaining = Math.floor(ms);
  const parts = [];
  for (const [unit, size] of UNITS) {
    const n = Math.floor(remaining / size);
    if (n > 0) parts.push(`${n}${unit}`);
    remaining -= n * size;
  }
  return parts.length > 0 ? parts.join('') : '0s';
}

module.exports = { parseDuration, formatDuration };
